export const GENERATED_QUESTION_BANK: BankQuestion[] = [
  { id: "lc-1", topic: "limit-calc", difficulty: 1 as 1 | 2 | 3, q: "lim(x→0) sin x / x = ?", options: ["0", "1", "∞", "不存在"], answer: 1, explain: "第一个重要极限：x→0 时 sin x 与 x 是等价无穷小，比值为 1。" },
  { id: "lc-2", topic: "limit-calc", difficulty: 1 as 1 | 2 | 3, q: "lim(x→0) tan x / x = ?", options: ["0", "∞", "1", "π"], answer: 2, explain: "tan x = sin x / cos x，极限 = lim sinx/x · lim 1/cosx = 1 × 1 = 1。" },
  { id: "lc-3", topic: "limit-calc", difficulty: 1 as 1 | 2 | 3, q: "lim(x→3) (x² − 9) / (x − 3) = ?", options: ["0", "3", "6", "不存在"], answer: 2, explain: "因式分解：(x²−9)/(x−3) = x + 3（x≠3），代入 x→3 得 6。" },
  { id: "lc-4", topic: "limit-calc", difficulty: 2 as 1 | 2 | 3, q: "lim(x→0) (1 − cos x) / x² = ?", options: ["0", "1", "1/2", "2"], answer: 2, explain: "1 − cos x = 2sin²(x/2) ~ x²/2，故极限为 1/2。" },
  { id: "lc-5", topic: "limit-calc", difficulty: 2 as 1 | 2 | 3, q: "lim(x→0) (eˣ − 1) / x = ?", options: ["0", "1", "e", "∞"], answer: 1, explain: "eˣ − 1 与 x 是等价无穷小；这也是 eˣ 在 x = 0 处的导数定义。" },
  { id: "lc-6", topic: "limit-calc", difficulty: 2 as 1 | 2 | 3, q: "lim(x→∞) (3x² + 1) / (x² + 5x) = ?", options: ["0", "1", "3", "∞"], answer: 2, explain: "同除以 x²：分子→3，分母→1，极限 = 3/1 = 3（最高次项系数之比）。" },
  { id: "lc-7", topic: "limit-calc", difficulty: 2 as 1 | 2 | 3, q: "lim(x→∞) (1 + 2/x)ˣ = ?", options: ["e", "e²", "1", "∞"], answer: 1, explain: "第二个重要极限的推广：(1 + a/x)ˣ → eᵃ，这里 a = 2。" },
  { id: "lc-8", topic: "limit-calc", difficulty: 3 as 1 | 2 | 3, q: "lim(n→∞) (1 + 1/n)ⁿ = ?", options: ["1", "∞", "e", "π"], answer: 2, explain: "第二个重要极限，自然常数 e ≈ 2.71828 的定义式之一。" },
  { id: "ln-1", topic: "limit-continuity", difficulty: 1 as 1 | 2 | 3, q: "f(x) = sin x / x 在 x = 0 处（f(0) 未定义）是？", options: ["连续点", "可去间断点", "跳跃间断点", "无穷间断点"], answer: 1, explain: "极限 lim sinx/x = 1 存在，但 f(0) 无定义；补上 f(0)=1 即连续，属可去间断点。" },
  { id: "ln-2", topic: "limit-continuity", difficulty: 1 as 1 | 2 | 3, q: "f(x) = |x| 在 x = 0 处？", options: ["可导", "连续但不可导", "不连续", "是跳跃间断点"], answer: 1, explain: "左右极限都是 0 = f(0)，连续；但左导数 −1 ≠ 右导数 1，不可导（尖点）。" },
  { id: "ln-3", topic: "limit-continuity", difficulty: 1 as 1 | 2 | 3, q: "「f 在 a 点连续」的严格定义是？", options: ["f(a) 有定义", "lim(x→a) f(x) 存在", "lim(x→a) f(x) = f(a)", "f′(a) 存在"], answer: 2, explain: "连续三要素：f(a) 有定义、极限存在、二者相等。可导是比连续更强的条件。" },
  { id: "ln-4", topic: "limit-continuity", difficulty: 2 as 1 | 2 | 3, q: "f(x) = 1/x 在 x = 0 处是？", options: ["可去间断点", "跳跃间断点", "无穷间断点", "连续点"], answer: 2, explain: "x→0 时 |f(x)|→∞，极限不存在且为无穷大，属第二类（无穷）间断点。" },
  { id: "ln-5", topic: "limit-continuity", difficulty: 2 as 1 | 2 | 3, q: "f(x) = { x (x<1)；x+1 (x≥1) } 在 x = 1 处是？", options: ["连续点", "可去间断点", "跳跃间断点", "无穷间断点"], answer: 2, explain: "左极限 = 1，右极限 = f(1) = 2，左右极限都存在但不相等 → 跳跃间断点。" },
  { id: "ln-6", topic: "limit-continuity", difficulty: 2 as 1 | 2 | 3, q: "f(x) = (x² − 1)/(x − 1) 在 x = 1 处是？", options: ["连续点", "可去间断点", "跳跃间断点", "无穷间断点"], answer: 1, explain: "化简得 x + 1（x≠1），极限 = 2 存在但 f(1) 无定义，补上 f(1)=2 即连续。" },
  { id: "ln-7", topic: "limit-continuity", difficulty: 3 as 1 | 2 | 3, q: "闭区间 [a, b] 上的连续函数一定？", options: ["有最大值和最小值", "有零点", "处处可导", "单调"], answer: 0, explain: "最值定理：闭区间上的连续函数必有界，且能取到最大值与最小值。" },
  { id: "ln-8", topic: "limit-continuity", difficulty: 3 as 1 | 2 | 3, q: "f 在 [a, b] 连续且 f(a)·f(b) < 0，则区间内至少有一点 c 使？", options: ["f(c) = 0", "f′(c) = 0", "f(c) 最大", "f(c) 不存在"], answer: 0, explain: "零点存在定理：连续函数在异号两端之间必然穿过 x 轴至少一次。" },
  { id: "dc-1", topic: "deriv-calc", difficulty: 1 as 1 | 2 | 3, q: "(x⁵)′ = ?", options: ["5x⁴", "x⁴", "4x⁵", "5x⁵"], answer: 0, explain: "幂函数求导：(xⁿ)′ = n·xⁿ⁻¹，n = 5 时得 5x⁴。" },
  { id: "dc-2", topic: "deriv-calc", difficulty: 1 as 1 | 2 | 3, q: "(sin x)′ = ?", options: ["−cos x", "cos x", "−sin x", "tan x"], answer: 1, explain: "基本公式：(sin x)′ = cos x；注意 (cos x)′ = −sin x 带负号。" },
  { id: "dc-3", topic: "deriv-calc", difficulty: 1 as 1 | 2 | 3, q: "(eˣ)′ = ?", options: ["xeˣ", "eˣ", "eˣ⁻¹", "ln x"], answer: 1, explain: "eˣ 是唯一「求导不变」的函数，这正是 e 的特殊之处。" },
  { id: "dc-4", topic: "deriv-calc", difficulty: 1 as 1 | 2 | 3, q: "(ln x)′ = ?", options: ["1/x", "ln x", "x", "eˣ"], answer: 0, explain: "基本公式：(ln x)′ = 1/x（x > 0）；与 ∫1/x dx = ln|x| 互为逆运算。" },
  { id: "dc-5", topic: "deriv-calc", difficulty: 2 as 1 | 2 | 3, q: "(sin 2x)′ = ?", options: ["cos 2x", "2cos 2x", "2sin 2x", "−2cos 2x"], answer: 1, explain: "链式法则：外层 sin 求导得 cos 2x，内层 2x 求导得 2，相乘 = 2cos 2x。" },
  { id: "dc-6", topic: "deriv-calc", difficulty: 2 as 1 | 2 | 3, q: "(x·eˣ)′ = ?", options: ["eˣ", "(x + 1)eˣ", "xeˣ", "eˣ + x"], answer: 1, explain: "乘积法则 (uv)′ = u′v + uv′：1·eˣ + x·eˣ = (x + 1)eˣ。" },
  { id: "dc-7", topic: "deriv-calc", difficulty: 2 as 1 | 2 | 3, q: "(ln 2x)′ = ?", options: ["1/x", "2/x", "1/(2x)", "ln 2"], answer: 0, explain: "链式法则：1/(2x) · 2 = 1/x。也可由 ln 2x = ln 2 + ln x 直接看出。" },
  { id: "dc-8", topic: "deriv-calc", difficulty: 3 as 1 | 2 | 3, q: "(2ˣ)′ = ?", options: ["x·2ˣ⁻¹", "2ˣ", "2ˣ·ln 2", "2ˣ⁻¹"], answer: 2, explain: "指数函数求导：(aˣ)′ = aˣ·ln a。别与幂函数 (xⁿ)′ = nxⁿ⁻¹ 混淆。" },
  { id: "dc-9", topic: "deriv-calc", difficulty: 3 as 1 | 2 | 3, q: "(tan x)′ = ?", options: ["sec²x", "cot x", "−csc²x", "cos²x"], answer: 0, explain: "由 sin x / cos x 用商法则可得 (tan x)′ = 1/cos²x = sec²x。" },
  { id: "da-1", topic: "deriv-app", difficulty: 1 as 1 | 2 | 3, q: "f(x) = x² 在 x = 3 处的切线斜率是？", options: ["3", "6", "9", "2"], answer: 1, explain: "f′(x) = 2x，x = 3 时斜率 = 6。导数的几何意义即切线斜率。" },
  { id: "da-2", topic: "deriv-app", difficulty: 1 as 1 | 2 | 3, q: "函数在某极值点 x₀ 处可导，则必有？", options: ["f′(x₀) = 0", "f′(x₀) > 0", "f′(x₀) < 0", "f″(x₀) = 0"], answer: 0, explain: "费马定理：可导函数在极值点处导数必为 0（驻点）；反之不一定成立。" },
  { id: "da-3", topic: "deriv-app", difficulty: 1 as 1 | 2 | 3, q: "在区间内 f′(x) > 0，则 f 在该区间？", options: ["单调递减", "单调递增", "取极大值", "恒为常数"], answer: 1, explain: "导数的符号决定单调性：f′ > 0 递增，f′ < 0 递减。" },
  { id: "da-4", topic: "deriv-app", difficulty: 2 as 1 | 2 | 3, q: "曲线 y = x² 在点 (1, 1) 处的切线方程是？", options: ["y = 2x − 1", "y = x", "y = 2x + 1", "y = x − 1"], answer: 0, explain: "斜率 f′(1) = 2，点斜式 y − 1 = 2(x − 1)，即 y = 2x − 1。" },
  { id: "da-5", topic: "deriv-app", difficulty: 2 as 1 | 2 | 3, q: "f(x) = x³ − 3x 的驻点是？", options: ["x = 0", "x = ±1", "x = ±3", "x = 3"], answer: 1, explain: "f′(x) = 3x² − 3 = 3(x² − 1) = 0，解得 x = ±1。" },
  { id: "da-6", topic: "deriv-app", difficulty: 2 as 1 | 2 | 3, q: "f′(a) = 0 且 f″(a) > 0，则 a 点是？", options: ["极大值点", "极小值点", "拐点", "间断点"], answer: 1, explain: "第二充分条件：驻点处二阶导数为正 → 函数局部下凹，取极小值。" },
  { id: "da-7", topic: "deriv-app", difficulty: 3 as 1 | 2 | 3, q: "洛必达法则适用于哪种极限？", options: ["任何极限", "0/0 或 ∞/∞ 型未定式", "仅多项式", "仅三角函数"], answer: 1, explain: "只有 0/0、∞/∞ 型才能直接洛必达；其他型（0·∞、1^∞ 等）需先变形。" },
  { id: "da-8", topic: "deriv-app", difficulty: 3 as 1 | 2 | 3, q: "lim(x→0) x / sin x 用洛必达法则得？", options: ["0", "1", "∞", "不存在"], answer: 1, explain: "0/0 型，分子分母分别求导：lim 1/cos x = 1。与重要极限互为倒数。" },
  { id: "ii-1", topic: "integral-indef", difficulty: 1 as 1 | 2 | 3, q: "∫ x² dx = ?", options: ["x³/3 + C", "2x + C", "x³ + C", "3x² + C"], answer: 0, explain: "幂函数积分：∫xⁿdx = xⁿ⁺¹/(n+1) + C（n ≠ −1）。别忘任意常数 C。" },
  { id: "ii-2", topic: "integral-indef", difficulty: 1 as 1 | 2 | 3, q: "∫ (1/x) dx = ?", options: ["ln|x| + C", "1/x² + C", "x⁰ + C", "eˣ + C"], answer: 0, explain: "n = −1 的特例：∫1/x dx = ln|x| + C（绝对值保证负数也有定义）。" },
  { id: "ii-3", topic: "integral-indef", difficulty: 1 as 1 | 2 | 3, q: "∫ cos x dx = ?", options: ["−sin x + C", "sin x + C", "cos x + C", "−cos x + C"], answer: 1, explain: "因为 (sin x)′ = cos x，所以 ∫cos x dx = sin x + C。" },
  { id: "ii-4", topic: "integral-indef", difficulty: 1 as 1 | 2 | 3, q: "∫ eˣ dx = ?", options: ["eˣ + C", "xeˣ + C", "eˣ⁺¹ + C", "ln x + C"], answer: 0, explain: "eˣ 求导不变，积分也不变：∫eˣ dx = eˣ + C。" },
  { id: "ii-5", topic: "integral-indef", difficulty: 2 as 1 | 2 | 3, q: "∫ 1/(1 + x²) dx = ?", options: ["arcsin x + C", "arctan x + C", "ln(1 + x²) + C", "1/x + C"], answer: 1, explain: "基本积分表：因为 (arctan x)′ = 1/(1 + x²)，故积分为 arctan x + C。" },
  { id: "ii-6", topic: "integral-indef", difficulty: 2 as 1 | 2 | 3, q: "∫ (2x + 1) dx = ?", options: ["x² + x + C", "2 + C", "x² + C", "2x² + x + C"], answer: 0, explain: "逐项积分：∫2x dx = x²，∫1 dx = x，合并得 x² + x + C。" },
  { id: "ii-7", topic: "integral-indef", difficulty: 3 as 1 | 2 | 3, q: "∫ 2x·cos(x²) dx = ?（凑微分）", options: ["cos(x²) + C", "sin(x²) + C", "2sin(x²) + C", "−sin(x²) + C"], answer: 1, explain: "注意到 2x 正是 x² 的导数：令 u = x²，原式 = ∫cos u du = sin(x²) + C。" },
  { id: "ii-8", topic: "integral-indef", difficulty: 3 as 1 | 2 | 3, q: "∫ 1/√(1 − x²) dx = ?", options: ["arccos x + C", "arctan x + C", "arcsin x + C", "√(1 − x²) + C"], answer: 2, explain: "因为 (arcsin x)′ = 1/√(1 − x²)，故积分为 arcsin x + C。" },
  { id: "id-1", topic: "integral-def", difficulty: 1 as 1 | 2 | 3, q: "∫₀¹ x dx = ?", options: ["1", "1/2", "2", "1/3"], answer: 1, explain: "原函数 x²/2，代入得 1/2 − 0 = 1/2（也是三角形的面积）。" },
  { id: "id-2", topic: "integral-def", difficulty: 1 as 1 | 2 | 3, q: "∫₀¹ x² dx = ?", options: ["1/2", "1/3", "1", "2/3"], answer: 1, explain: "原函数 x³/3，代入得 1/3 − 0 = 1/3。" },
  { id: "id-3", topic: "integral-def", difficulty: 1 as 1 | 2 | 3, q: "牛顿-莱布尼茨公式：∫ₐᵇ f(x)dx = ?", options: ["F(b) − F(a)", "f(b) − f(a)", "F(a) − F(b)", "f′(b) − f′(a)"], answer: 0, explain: "F 是 f 的任一原函数，定积分 = 原函数在上下限处的差 F(b) − F(a)。" },
  { id: "id-4", topic: "integral-def", difficulty: 2 as 1 | 2 | 3, q: "∫₀^π sin x dx = ?", options: ["0", "1", "2", "π"], answer: 2, explain: "原函数 −cos x：−cos π − (−cos 0) = 1 + 1 = 2（半拱正弦的面积）。" },
  { id: "id-5", topic: "integral-def", difficulty: 2 as 1 | 2 | 3, q: "∫₋₁¹ x³ dx = ?", options: ["2", "1", "0", "1/4"], answer: 2, explain: "x³ 是奇函数，在对称区间 [−1, 1] 上正负面积相消，积分为 0。" },
  { id: "id-6", topic: "integral-def", difficulty: 2 as 1 | 2 | 3, q: "∫₀¹ eˣ dx = ?", options: ["e", "e − 1", "1", "e + 1"], answer: 1, explain: "原函数 eˣ：e¹ − e⁰ = e − 1。" },
  { id: "id-7", topic: "integral-def", difficulty: 3 as 1 | 2 | 3, q: "∫₁^e (1/x) dx = ?", options: ["e", "1", "e − 1", "1/e"], answer: 1, explain: "原函数 ln x：ln e − ln 1 = 1 − 0 = 1。" },
  { id: "id-8", topic: "integral-def", difficulty: 3 as 1 | 2 | 3, q: "当 f(x) ≥ 0 时，∫ₐᵇ f(x)dx 的几何意义是？", options: ["曲线的弧长", "曲边梯形的面积", "旋转体体积", "切线斜率"], answer: 1, explain: "定积分是「无穷小矩形面积之和」的极限，即曲线下的曲边梯形面积。" },
  { id: "se-1", topic: "series", difficulty: 1 as 1 | 2 | 3, q: "几何级数 Σ (1/2)ⁿ（n 从 0 到 ∞）= ?", options: ["1", "3/2", "2", "发散"], answer: 2, explain: "首项 a = 1，公比 r = 1/2，和 = a/(1 − r) = 1/(1/2) = 2。" },
  { id: "se-2", topic: "series", difficulty: 1 as 1 | 2 | 3, q: "几何级数 Σ rⁿ 收敛的条件是？", options: ["r < 1", "|r| < 1", "r > 0", "|r| ≤ 1"], answer: 1, explain: "|r| < 1 时收敛于 1/(1 − r)；|r| ≥ 1 时通项不趋于 0，必发散。" },
  { id: "se-3", topic: "series", difficulty: 1 as 1 | 2 | 3, q: "调和级数 Σ 1/n（n=1..∞）？", options: ["收敛于 1", "收敛于 e", "发散", "收敛于 0"], answer: 2, explain: "虽然 1/n → 0，但部分和增长如 ln n，缓慢地趋向无穷 —— 发散。" },
  { id: "se-4", topic: "series", difficulty: 2 as 1 | 2 | 3, q: "p-级数 Σ 1/nᵖ 收敛当且仅当？", options: ["p > 0", "p ≥ 1", "p > 1", "p < 1"], answer: 2, explain: "与积分 ∫1/xᵖ 比较：p > 1 收敛（如 1/n²），p ≤ 1 发散（如调和级数）。" },
  { id: "se-5", topic: "series", difficulty: 2 as 1 | 2 | 3, q: "级数 Σ aₙ 收敛的必要条件是？", options: ["aₙ → 0", "部分和有界", "aₙ > 0", "aₙ 单调递减"], answer: 0, explain: "收敛 ⟹ 通项趋于 0；但通项趋于 0 不保证收敛（调和级数就是反例）。" },
  { id: "se-6", topic: "series", difficulty: 2 as 1 | 2 | 3, q: "「aₙ → 0」是级数 Σ aₙ 收敛的？", options: ["充要条件", "充分非必要条件", "必要非充分条件", "无关条件"], answer: 2, explain: "收敛必须有 aₙ → 0（必要），但 aₙ → 0 不足以推出收敛（不充分）。" },
  { id: "se-7", topic: "series", difficulty: 3 as 1 | 2 | 3, q: "Σ 1/n² = ?（巴塞尔问题）", options: ["π/2", "π²/6", "e", "2"], answer: 1, explain: "欧拉证明的著名结果：1 + 1/4 + 1/9 + … = π²/6 ≈ 1.6449。" },
  { id: "se-8", topic: "series", difficulty: 3 as 1 | 2 | 3, q: "eˣ 的泰勒级数（麦克劳林展开）是？", options: ["Σ xⁿ/n!", "Σ xⁿ", "Σ (−1)ⁿxⁿ", "Σ n·xⁿ"], answer: 0, explain: "eˣ = 1 + x + x²/2! + x³/3! + …，代入 x = 1 可得 e 的级数定义。" },
  { id: "la-mat-1", topic: "matrix-basics", difficulty: 1 as 1 | 2 | 3, q: "行列式 det([[1,2],[3,4]]) = ?", options: ["-2", "2", "-1", "10"], answer: 0, explain: "det = 1×4 − 2×3 = 4 − 6 = −2。" },
  { id: "la-mat-2", topic: "matrix-basics", difficulty: 1 as 1 | 2 | 3, q: "矩阵 A = [[1,0],[0,2]] 的行列式是？", options: ["0", "1", "2", "3"], answer: 2, explain: "对角矩阵的行列式等于对角线元素之积：1×2 = 2。" },
  { id: "la-mat-3", topic: "matrix-basics", difficulty: 2 as 1 | 2 | 3, q: "若 2×2 矩阵的行列式为 0，则该矩阵？", options: ["可逆", "奇异（不可逆）", "正定", "是单位矩阵"], answer: 1, explain: "det = 0 意味着矩阵不可逆（奇异），对应的线性变换把平面压扁。" },
  { id: "la-mat-4", topic: "matrix-basics", difficulty: 2 as 1 | 2 | 3, q: "矩阵 [[3,1],[2,5]] 的迹（trace）是？", options: ["6", "7", "8", "10"], answer: 2, explain: "迹是主对角线元素之和：3 + 5 = 8。" },
  { id: "la-mat-5", topic: "matrix-basics", difficulty: 2 as 1 | 2 | 3, q: "设 A = [[1,2],[3,4]]，则 2A 的第 2 行第 1 列元素是？", options: ["3", "4", "6", "8"], answer: 2, explain: "数乘逐元素进行：2 × 3 = 6。" },
  { id: "la-mat-6", topic: "matrix-basics", difficulty: 2 as 1 | 2 | 3, q: "矩阵乘法一般不满足哪条性质？", options: ["结合律", "分配律", "交换律", "与单位阵相乘不变"], answer: 2, explain: "矩阵乘法满足结合律与分配律，但一般 AB ≠ BA，不满足交换律。" },
  { id: "la-mat-7", topic: "matrix-basics", difficulty: 3 as 1 | 2 | 3, q: "det([[a,b],[c,d]]) 的正确公式是？", options: ["ad + bc", "ad − bc", "ab − cd", "ac − bd"], answer: 1, explain: "二阶行列式 = 主对角线之积 − 副对角线之积 = ad − bc。" },
  { id: "la-mat-8", topic: "matrix-basics", difficulty: 3 as 1 | 2 | 3, q: "线性变换把单位正方形变成平行四边形，其面积等于？", options: ["矩阵的迹", "矩阵的秩", "变换矩阵行列式的绝对值", "特征值的和"], answer: 2, explain: "行列式的几何意义就是面积（体积）的伸缩倍数，取绝对值得到面积。" },
  { id: "la-sys-1", topic: "linear-systems", difficulty: 1 as 1 | 2 | 3, q: "方程组 x + y = 3, x − y = 1 的解是？", options: ["x=1,y=2", "x=2,y=1", "x=3,y=0", "x=0,y=3"], answer: 1, explain: "两式相加得 2x=4 → x=2，代回得 y=1。" },
  { id: "la-sys-2", topic: "linear-systems", difficulty: 2 as 1 | 2 | 3, q: "若系数矩阵的行列式不为 0，则齐次方程组 Ax = 0？", options: ["只有零解", "有无穷多解", "无解", "无法判断"], answer: 0, explain: "det(A) ≠ 0 时 A 可逆，两边左乘 A⁻¹ 得 x = 0，只有零解。" },
  { id: "la-sys-3", topic: "linear-systems", difficulty: 2 as 1 | 2 | 3, q: "方程组 x + y = 1, 2x + 2y = 3 的解的情况是？", options: ["唯一解", "无解", "无穷多解", "无穷多解但需参数"], answer: 1, explain: "第二式左端是第一式的 2 倍，右端却是 3 而非 2，两直线平行不重合，无解。" },
  { id: "la-sys-4", topic: "linear-systems", difficulty: 2 as 1 | 2 | 3, q: "方程组 x + y = 1, x + y = 2 的解的情况是？", options: ["唯一解", "无解", "无穷多解", "不确定"], answer: 1, explain: "左端相同右端不同，两条直线平行，无解。" },
  { id: "la-sys-5", topic: "linear-systems", difficulty: 2 as 1 | 2 | 3, q: "矩阵 [[1,2],[2,4]] 的秩是？", options: ["0", "1", "2", "3"], answer: 1, explain: "第二行是第一行的 2 倍，行向量线性相关，只有一个线性无关行，秩为 1。" },
  { id: "la-sys-6", topic: "linear-systems", difficulty: 3 as 1 | 2 | 3, q: "对非齐次方程组 Ax = b，若 rank(A) = rank([A|b]) < n，则？", options: ["无解", "唯一解", "无穷多解", "只有零解"], answer: 2, explain: "系数矩阵与增广矩阵同秩说明有解，秩小于未知数个数说明有无穷多解。" },
  { id: "la-sys-7", topic: "linear-systems", difficulty: 3 as 1 | 2 | 3, q: "方程组 2x + 4y = 6, x + 2y = 3 的解是？", options: ["唯一解 (1,1)", "无解", "无穷多解", "x=3,y=0"], answer: 2, explain: "第二式乘 2 即第一式，两方程等价，表示同一直线，有无穷多解。" },
  { id: "la-sys-8", topic: "linear-systems", difficulty: 3 as 1 | 2 | 3, q: "齐次方程组有非零解的充要条件是？", options: ["det(A) = 0", "det(A) ≠ 0", "rank(A) = n", "A 是对称阵"], answer: 0, explain: "det(A) = 0（等价于 rank(A) < n）时，齐次方程组有非零解。" },
  { id: "la-eig-1", topic: "eigenvalues", difficulty: 1 as 1 | 2 | 3, q: "若 Av = 2v（v ≠ 0），则 2 是 A 的？", options: ["行列式", "特征值", "迹", "秩"], answer: 1, explain: "满足 Av = λv 的 λ 称为特征值，v 是对应特征向量。" },
  { id: "la-eig-2", topic: "eigenvalues", difficulty: 2 as 1 | 2 | 3, q: "对角矩阵 [[2,0],[0,3]] 的特征值是？", options: ["2 和 3", "0 和 5", "2 和 0", "1 和 6"], answer: 0, explain: "对角矩阵的特征值就是对角线元素：2 和 3。" },
  { id: "la-eig-3", topic: "eigenvalues", difficulty: 2 as 1 | 2 | 3, q: "矩阵 A = [[2,1],[1,2]] 较大的特征值是？", options: ["1", "2", "3", "4"], answer: 2, explain: "特征方程 (2−λ)²−1=0 → λ=1 或 3，较大者为 3。" },
  { id: "la-eig-4", topic: "eigenvalues", difficulty: 2 as 1 | 2 | 3, q: "二阶矩阵特征值之积等于？", options: ["迹", "行列式", "秩", "对角线元素和"], answer: 1, explain: "特征值之积 = det(A)，特征值之和 = tr(A)。" },
  { id: "la-eig-5", topic: "eigenvalues", difficulty: 2 as 1 | 2 | 3, q: "特征值通过解哪个方程求得？", options: ["Ax = b", "det(A − λI) = 0", "tr(A) = λ", "A + λI = 0"], answer: 1, explain: "特征方程 det(A − λI) = 0 的非零解条件给出特征值。" },
  { id: "la-eig-6", topic: "eigenvalues", difficulty: 3 as 1 | 2 | 3, q: "旋转 90° 的矩阵 [[0,−1],[1,0]] 的特征值是？", options: ["1 和 −1", "i 和 −i", "0 和 1", "都是 1"], answer: 1, explain: "特征方程 λ²+1=0，在复数域特征值为 ±i，说明实平面上无不变方向。" },
  { id: "la-eig-7", topic: "eigenvalues", difficulty: 3 as 1 | 2 | 3, q: "实对称矩阵的特征值必定？", options: ["全为 0", "全为实数", "全为正数", "互为相反数"], answer: 1, explain: "实对称矩阵可正交对角化，特征值必为实数。" },
  { id: "la-eig-8", topic: "eigenvalues", difficulty: 3 as 1 | 2 | 3, q: "若矩阵有 n 个线性无关特征向量，则该矩阵？", options: ["一定可逆", "可对角化", "一定对称", "秩为 n"], answer: 1, explain: "n 个线性无关特征向量构成一组基，矩阵可对角化（但不一定可逆或对称）。" },
  { id: "st-prob-1", topic: "probability-basics", difficulty: 1 as 1 | 2 | 3, q: "掷一枚均匀骰子，出现偶数点的概率是？", options: ["1/6", "1/3", "1/2", "2/3"], answer: 2, explain: "偶数点有 2、4、6 共 3 种，概率 3/6 = 1/2。" },
  { id: "st-prob-2", topic: "probability-basics", difficulty: 2 as 1 | 2 | 3, q: "若事件 A、B 互斥，则 P(A∪B) = ?", options: ["P(A)·P(B)", "P(A)+P(B)", "P(A)−P(B)", "P(A|B)"], answer: 1, explain: "互斥事件不能同时发生，并集概率等于概率之和。" },
  { id: "st-prob-3", topic: "probability-basics", difficulty: 2 as 1 | 2 | 3, q: "若事件 A、B 相互独立，则 P(A∩B) = ?", options: ["P(A)+P(B)", "P(A)·P(B)", "0", "P(A|B)"], answer: 1, explain: "独立性定义：P(A∩B) = P(A)·P(B)。" },
  { id: "st-prob-4", topic: "probability-basics", difficulty: 2 as 1 | 2 | 3, q: "条件概率 P(A|B) 的正确公式是？", options: ["P(A)·P(B)", "P(AB)/P(B)", "P(B)/P(A)", "P(A)+P(B)"], answer: 1, explain: "P(A|B) = P(A∩B) / P(B)，要求 P(B) > 0。" },
  { id: "st-prob-5", topic: "probability-basics", difficulty: 2 as 1 | 2 | 3, q: "P(A) = 0.6，P(B) = 0.5，若 A、B 独立，则 P(A∩B) = ?", options: ["0.1", "0.3", "0.8", "1.1"], answer: 1, explain: "独立事件：0.6 × 0.5 = 0.3。" },
  { id: "st-prob-6", topic: "probability-basics", difficulty: 3 as 1 | 2 | 3, q: "从 52 张扑克牌中随机抽 1 张，抽到 A 的概率是？", options: ["1/52", "1/26", "1/13", "4/13"], answer: 2, explain: "4 张 A，概率 4/52 = 1/13。" },
  { id: "st-prob-7", topic: "probability-basics", difficulty: 3 as 1 | 2 | 3, q: "全概率公式用于？", options: ["求条件概率", "把复杂事件按划分分解求概率", "求期望", "检验独立性"], answer: 1, explain: "全概率公式 P(A)=ΣP(Bᵢ)P(A|Bᵢ)，按样本空间划分分解。" },
  { id: "st-prob-8", topic: "probability-basics", difficulty: 3 as 1 | 2 | 3, q: "贝叶斯公式的核心作用是？", options: ["由结果反推原因的概率", "求方差", "判断独立", "求分布函数"], answer: 0, explain: "贝叶斯公式由 P(A|B) 反推 P(B|A)，即由观察结果更新对原因的信念。" },
  { id: "st-dist-1", topic: "distributions", difficulty: 1 as 1 | 2 | 3, q: "二项分布 B(n, p) 的期望是？", options: ["p", "np", "np(1−p)", "n"], answer: 1, explain: "二项分布期望 E[X] = np，方差 Var(X) = np(1−p)。" },
  { id: "st-dist-2", topic: "distributions", difficulty: 2 as 1 | 2 | 3, q: "泊松分布 P(λ) 的期望和方差分别是？", options: ["λ, λ", "λ, λ²", "1/λ, 1/λ²", "λ², λ"], answer: 0, explain: "泊松分布的期望与方差都等于参数 λ。" },
  { id: "st-dist-3", topic: "distributions", difficulty: 2 as 1 | 2 | 3, q: "正态分布 N(μ, σ²) 中的 μ 表示？", options: ["方差", "标准差", "期望（均值）", "中位数倍数"], answer: 2, explain: "N(μ, σ²) 中 μ 是期望，σ² 是方差，曲线关于 x=μ 对称。" },
  { id: "st-dist-4", topic: "distributions", difficulty: 2 as 1 | 2 | 3, q: "方差的正确计算公式是？", options: ["E(X²)", "E(X²) − [E(X)]²", "[E(X)]²", "E(X)² − E(X²)"], answer: 1, explain: "Var(X) = E(X²) − [E(X)]²。" },
  { id: "st-dist-5", topic: "distributions", difficulty: 2 as 1 | 2 | 3, q: "均匀分布 U(0, 10) 的期望是？", options: ["0", "5", "10", "50"], answer: 1, explain: "均匀分布 U(a,b) 的期望 = (a+b)/2 = 5。" },
  { id: "st-dist-6", topic: "distributions", difficulty: 3 as 1 | 2 | 3, q: "指数分布 Exp(λ) 的期望是？", options: ["λ", "λ²", "1/λ", "1/λ²"], answer: 2, explain: "指数分布期望 E[X] = 1/λ，常用来建模等待时间。" },
  { id: "st-dist-7", topic: "distributions", difficulty: 3 as 1 | 2 | 3, q: "X ~ B(20, 0.5)，则 Var(X) = ?", options: ["5", "10", "20", "2.5"], answer: 0, explain: "Var = np(1−p) = 20 × 0.5 × 0.5 = 5。" },
  { id: "st-dist-8", topic: "distributions", difficulty: 3 as 1 | 2 | 3, q: "标准正态分布是指？", options: ["N(0,1)", "N(1,1)", "N(0,0)", "均值为 1 的正态分布"], answer: 0, explain: "标准正态分布期望 0、方差 1，记作 N(0,1)。" },
  { id: "st-clt-1", topic: "central-limit", difficulty: 2 as 1 | 2 | 3, q: "中心极限定理说明，当 n 很大时样本均值近似服从？", options: ["原总体分布", "正态分布", "均匀分布", "二项分布"], answer: 1, explain: "CLT：无论总体分布如何，n 足够大时样本均值近似正态。" },
  { id: "st-clt-2", topic: "central-limit", difficulty: 2 as 1 | 2 | 3, q: "样本均值的标准误（SE）等于？", options: ["σ", "σ/n", "σ/√n", "σ²/n"], answer: 2, explain: "标准误 SE = σ/√n，随样本量增大而减小。" },
  { id: "st-clt-3", topic: "central-limit", difficulty: 2 as 1 | 2 | 3, q: "总体标准差 σ=20，样本量 n=100，则标准误为？", options: ["20", "2", "0.2", "200"], answer: 1, explain: "SE = 20/√100 = 20/10 = 2。" },
  { id: "st-clt-4", topic: "central-limit", difficulty: 3 as 1 | 2 | 3, q: "关于中心极限定理，下列说法正确的是？", options: ["要求总体必须正态", "要求 n 必须大于 1000", "不要求总体正态，但需 n 足够大", "只适用于离散分布"], answer: 2, explain: "CLT 的关键是 n 足够大，对总体分布形态没有严格要求（需有限方差）。" },
  { id: "st-clt-5", topic: "central-limit", difficulty: 3 as 1 | 2 | 3, q: "大数定律描述的是？", options: ["样本均值收敛到期望", "样本均值服从正态", "方差趋于 0", "分布趋于均匀"], answer: 0, explain: "大数定律：随着样本量增加，样本均值依概率收敛到总体期望。" },
  { id: "st-clt-6", topic: "central-limit", difficulty: 3 as 1 | 2 | 3, q: "样本量 n 增大 4 倍，标准误变为原来的？", options: ["4 倍", "2 倍", "1/2", "1/4"], answer: 2, explain: "SE = σ/√n，n 变 4 倍则 √n 变 2 倍，SE 减半。" },
  { id: "st-clt-7", topic: "central-limit", difficulty: 3 as 1 | 2 | 3, q: "样本均值分布的中心位置是？", options: ["0", "总体期望 μ", "总体方差 σ²", "样本方差"], answer: 1, explain: "样本均值的期望等于总体期望 μ，分布围绕 μ 展开。" },
  { id: "st-clt-8", topic: "central-limit", difficulty: 3 as 1 | 2 | 3, q: "标准误衡量的是？", options: ["总体的离散程度", "样本均值的抽样波动大小", "样本量大小", "置信水平"], answer: 1, explain: "标准误是样本均值分布的标准差，反映抽样均值的波动。" },
  { id: "st-test-1", topic: "hypothesis-testing", difficulty: 2 as 1 | 2 | 3, q: "当 p 值小于显著性水平 α 时，应当？", options: ["拒绝原假设", "接受原假设", "无法判断", "增大样本量"], answer: 0, explain: "p < α 说明结果在原假设下很不可能，拒绝原假设。" },
  { id: "st-test-2", topic: "hypothesis-testing", difficulty: 2 as 1 | 2 | 3, q: "原假设 H₀ 通常表示？", options: ["研究者想证明的效应", "无效应 / 无差异的默认状态", "一定成立的命题", "备择假设的反面且必然为真"], answer: 1, explain: "H₀ 是默认的'无差异'陈述，检验是看数据是否提供足够证据拒绝它。" },
  { id: "st-test-3", topic: "hypothesis-testing", difficulty: 2 as 1 | 2 | 3, q: "显著性水平 α 是？", options: ["犯第一类错误的最大概率", "p 值的别名", "置信区间的宽度", "样本量"], answer: 0, explain: "α = P(拒绝 H₀ | H₀ 真)，即第一类错误（弃真）的概率上限。" },
  { id: "st-test-4", topic: "hypothesis-testing", difficulty: 3 as 1 | 2 | 3, q: "z 检验统计量 z = 2，双侧检验的 p 值约为？", options: ["0.0455", "0.0228", "0.95", "0.5"], answer: 0, explain: "P(|Z|≥2) = 2×(1−Φ(2)) ≈ 2×0.0228 = 0.0455。" },
  { id: "st-test-5", topic: "hypothesis-testing", difficulty: 3 as 1 | 2 | 3, q: "p 值的正确含义是？", options: ["H₀ 为真的概率", "H₀ 成立时观察到当前或更极端结果的概率", "备择假设为真的概率", "检验统计量的值"], answer: 1, explain: "p 值是条件于 H₀ 成立时，得到当前这样极端数据的概率，不是 H₀ 为真的概率。" },
  { id: "st-test-6", topic: "hypothesis-testing", difficulty: 3 as 1 | 2 | 3, q: "95% 置信区间对应的双侧显著性水平是？", options: ["α = 0.05", "α = 0.95", "α = 0.025", "α = 0.5"], answer: 0, explain: "置信度 1−α = 0.95，故 α = 0.05，双侧各 0.025。" },
  { id: "st-test-7", topic: "hypothesis-testing", difficulty: 3 as 1 | 2 | 3, q: "'不能拒绝 H₀' 意味着？", options: ["H₀ 一定为真", "证据不足以拒绝 H₀", "接受了备择假设", "检验出错"], answer: 1, explain: "不拒绝不等于接受，只说明当前数据不足以推翻 H₀。" },
  { id: "st-test-8", topic: "hypothesis-testing", difficulty: 3 as 1 | 2 | 3, q: "小样本（n 较小）且总体标准差未知时，宜使用？", options: ["z 检验", "t 检验", "卡方检验", "F 检验"], answer: 1, explain: "此时用 t 检验，统计量服从自由度为 n−1 的 t 分布。" },
]
